package com.hoteluq.pattern.creational;
import com.hoteluq.model.*;import java.time.LocalDate;import java.util.*;
public class ReservationBuilder {private User customer;private Room room;private LocalDate in,out;private final List<AdditionalService> services=new ArrayList<>();public ReservationBuilder customer(User v){customer=v;return this;}public ReservationBuilder room(Room v){room=v;return this;}public ReservationBuilder dates(LocalDate a,LocalDate b){in=a;out=b;return this;}public ReservationBuilder addService(AdditionalService s){services.add(s);return this;}public Reservation build(){if(customer==null||room==null||in==null||out==null||!out.isAfter(in))throw new IllegalStateException("Faltan datos de reserva");double extras=services.stream().mapToDouble(AdditionalService::price).sum();double total=room.getPricePerNight()*java.time.temporal.ChronoUnit.DAYS.between(in,out)+extras;return new Reservation(customer,room,in,out,services,total);}}
